javas.java:

int def overdueStage(int:overdueDays) {
    if (overdueDays >= 90) {
        return 4;
    } else if (overdueDays >= 60) {
        return 3;
    } else if (overdueDays >= 30) {
        return 2;
    } else if (overdueDays >= 1) {
        return 1;
    } else {
        return 0;
    }
}


int def scoreOverdueDays(int:overdueDays, int:overdueHistoryCount) {
    int score = 0;
    if (overdueDays >= 90) {
        score = 35;
    } else if (overdueDays >= 60) {
        score = 28;
    } else if (overdueDays >= 30) {
        score = 22;
    } else if (overdueDays >= 7) {
        score = 15;
    } else if (overdueDays >= 1) {
        score = 8;
    }
    if (overdueHistoryCount >= 3) {
        score = score - 10;
    } else if (overdueHistoryCount >= 1) {
        score = score - 5;
    }
    if (score < 0) {
        score = 0;
    }
    return score;
}


int def scoreAmountRatio(double:overdueAmount, double:remainingPrincipal) {
    if (remainingPrincipal <= 0.0 || overdueAmount <= 0.0) {
        return 0;
    }
    double ratio = overdueAmount / remainingPrincipal;
    if (ratio >= 0.5) {
        return 25;
    } else if (ratio >= 0.3) {
        return 20;
    } else if (ratio >= 0.15) {
        return 14;
    } else if (ratio >= 0.05) {
        return 8;
    } else {
        return 4;
    }
}


int def scoreContact(boolean:contactSuccess, int:lastContactDays) {
    int score = 0;
    if (contactSuccess) {
        if (lastContactDays <= 3) {
            score = 15;
        } else if (lastContactDays <= 7) {
            score = 10;
        } else {
            score = 5;
        }
    }
    return score;
}


int def scoreCollateral(str:collateralType, double:collateralValue, double:remainingPrincipal) {
    if (remainingPrincipal <= 0.0) {
        return 0;
    }
    if (collateralType == "HOUSE") {
        double cover = collateralValue / remainingPrincipal;
        if (cover >= 1.2) {
            return 25;
        } else if (cover >= 0.8) {
            return 18;
        } else {
            return 10;
        }
    } else if (collateralType == "VEHICLE") {
        double cover = collateralValue / remainingPrincipal;
        if (cover >= 1.2) {
            return 15;
        } else if (cover >= 0.8) {
            return 10;
        } else {
            return 5;
        }
    } else {
        return 0;
    }
}


str def warningLevel(int:warningScore) {
    if (warningScore >= 80) {
        return "RED";
    } else if (warningScore >= 60) {
        return "ORANGE";
    } else if (warningScore >= 40) {
        return "YELLOW";
    } else {
        return "BLUE";
    }
}


str def collectChannel(int:warningScore, double:overdueAmount) {
    if (warningScore >= 80) {
        return "LITIGATION";
    } else if (warningScore >= 60 && overdueAmount >= 100000.0) {
        return "LITIGATION";
    } else if (warningScore >= 60) {
        return "HOME_VISIT";
    } else if (warningScore >= 40) {
        return "PHONE";
    } else {
        return "SMS";
    }
}


double def penaltyInterest(double:remainingPrincipal, double:baseRate, int:overdueDays) {
    double penaltyRate = baseRate * 1.5;
    double interest = remainingPrincipal * penaltyRate / 365.0 * overdueDays;
    return interest;
}


double def minRepayAmount(double:overdueAmount, int:overdueDays) {
    double penaltyRatio = 0.01;
    if (overdueDays >= 90) {
        penaltyRatio = 0.05;
    } else if (overdueDays >= 30) {
        penaltyRatio = 0.03;
    }
    return overdueAmount + overdueAmount * penaltyRatio;
}


int def riskMigration(int:overdueStage, int:warningCount) {
    int migration = overdueStage * 2 + warningCount;
    if (migration > 9) {
        migration = 9;
    }
    return migration;
}
